const colors=['#b2dfa0','#ff8066','#b79ddd','#e7f58b','#a8d8d3','#dfa0bf','#91bafa','#ffca91'];
const board=document.querySelector('#board'),statusEl=document.querySelector('#status');
let regions=[],solution=[],marks=Array(64).fill(0),won=false,started=0,elapsed=0,number=1,gesture=null,assist=false,autoMarks=new Set(),history=[];
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function solve(reg,limit=2){let answers=[],path=[];function go(r,cols,groups){if(answers.length>=limit)return;if(r===8){answers.push([...path]);return}for(let c=0;c<8;c++){let g=reg[r*8+c];if((cols&(1<<c))||(groups&(1<<g))||(r&&Math.abs(path[r-1]-c)<=1))continue;path.push(c);go(r+1,cols|(1<<c),groups|(1<<g));path.pop()}}go(0,0,0);return answers}
function drawRegionLines(){let lines=[];for(let r=0;r<8;r++)for(let c=0;c<8;c++){let i=r*8+c;if(c<7&&regions[i]!==regions[i+1])lines.push('M '+((c+1)*100)+' '+(r*100)+' v 100');if(r<7&&regions[i]!==regions[i+8])lines.push('M '+(c*100)+' '+((r+1)*100)+' h 100')}document.querySelector('#region-lines').innerHTML='<path d="'+lines.join(' ')+'"/>'}
function render(){drawRegionLines();board.innerHTML='';for(let i=0;i<64;i++){let el=document.createElement('button');el.type='button';el.className='cell';el.dataset.index=i;el.style.setProperty('--color',colors[regions[i]]);if(i%8<7&&regions[i]!==regions[i+1])el.classList.add('edge-r');if(i<56&&regions[i]!==regions[i+8])el.classList.add('edge-b');el.setAttribute('aria-label',`第 ${1+(i>>3)} 行，第 ${1+i%8} 列，色塊 ${regions[i]+1}`);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();cycle(i)}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();let j=i+({ArrowLeft:-1,ArrowRight:1,ArrowUp:-8,ArrowDown:8}[e.key]);if(j>=0&&j<64)board.children[j].focus()}});board.append(el)}update(false)}
function computeAutoMarks(){autoMarks=new Set();if(!assist)return;const queens=marks.map((m,i)=>m===1?i:-1).filter(i=>i>=0);for(let i=0;i<64;i++){if(marks[i]===1)continue;for(const q of queens){const dr=Math.abs((i>>3)-(q>>3)),dc=Math.abs(i%8-q%8);if(!dr||!dc||regions[i]===regions[q]||(dr<=1&&dc<=1)){autoMarks.add(i);break}}}}
function syncUndo(){document.querySelector('#undo').disabled=history.length===0||gesture!==null}
function remember(){history.push([...marks]);if(history.length>200)history.shift()}
function undo(){if(!history.length||gesture)return;if(won)started=Date.now()-elapsed*1000;marks=history.pop();update(false)}
function finishGesture(){gesture=null;syncUndo()}
function update(celebrate=true){syncUndo();computeAutoMarks();document.querySelector('#assist').checked=assist;const wasWon=won;let queens=marks.map((m,i)=>m===1?i:-1).filter(i=>i>=0),bad=new Set();for(let a=0;a<queens.length;a++)for(let b=a+1;b<queens.length;b++){let i=queens[a],j=queens[b],dr=Math.abs((i>>3)-(j>>3)),dc=Math.abs(i%8-j%8);if(!dr||!dc||regions[i]===regions[j]||(dr<=1&&dc<=1)){bad.add(i);bad.add(j)}}won=queens.length===8&&!bad.size;board.classList.toggle('completed',won);Array.from(board.children).forEach((el,i)=>{el.disabled=won;el.classList.toggle('celebrate',won&&!wasWon&&celebrate&&marks[i]===1);el.style.setProperty('--flip-delay',(queens.indexOf(i)*0.14)+'s');const excluded=marks[i]===2||autoMarks.has(i);el.textContent=marks[i]===1?'♛':excluded?'×':'';el.classList.toggle('auto-mark',marks[i]===0&&autoMarks.has(i));if(marks[i]===1)el.innerHTML='<span class="queen-piece" aria-hidden="true">♛</span>';el.classList.toggle('mark',excluded);el.classList.toggle('bad',bad.has(i));el.setAttribute('aria-label',`第 ${1+(i>>3)} 行，第 ${1+i%8} 列，色塊 ${regions[i]+1}，${marks[i]===1?'皇后':excluded?(marks[i]===2?'排除':'輔助排除'):'空白'}${bad.has(i)?'，衝突':''}`)});document.querySelector('#count').textContent=queens.length+' / 8';statusEl.classList.toggle('win',won);statusEl.textContent=won?'✧ 花園完成！八位皇后都找到自己的位置。':bad.size?'有皇后靠得太近，或在同一行、列、色塊。':queens.length?`已安置 ${queens.length} 位皇后，繼續探索。`:'讓第一位皇后入座吧。';save()}
function start(){if(!started)started=Date.now()-elapsed*1000}
function cycle(i){if(won)return;remember();start();marks[i]=[2,0,1][marks[i]===0&&autoMarks.has(i)?2:marks[i]];update()}
function save(){try{localStorage.setItem('queens-garden-v2',JSON.stringify({regions,solution,marks,number,elapsed,assist,history}))}catch{}}
function newGame(){const p=puzzles[(number-1)%puzzles.length];regions=[...p.reg];solution=[...p.q];marks=Array(64).fill(0);history=[];won=false;started=0;elapsed=0;document.querySelector('#timer').textContent='00:00';document.querySelector('#level').textContent='花園 '+String(number).padStart(3,'0');render()}
board.addEventListener('pointerdown',e=>{let cell=e.target.closest('.cell');if(!cell||won||e.button!==0)return;e.preventDefault();let i=Number(cell.dataset.index);gesture={id:e.pointerId,start:i,x:e.clientX,y:e.clientY,drag:false,visited:new Set()};syncUndo();board.setPointerCapture(e.pointerId)});
board.addEventListener('pointermove',e=>{if(!gesture||gesture.id!==e.pointerId)return;if(!gesture.drag&&Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)>7){gesture.drag=true;paint(gesture.start)}if(gesture.drag){let el=document.elementFromPoint(e.clientX,e.clientY)?.closest('.cell');if(el&&board.contains(el))paint(Number(el.dataset.index))}});
function paint(i){if(!gesture||won||gesture.visited.has(i))return;gesture.visited.add(i);if(marks[i]===2)return;if(!gesture.recorded){remember();gesture.recorded=true}start();marks[i]=2;update()}
board.addEventListener('pointerup',e=>{if(!gesture||gesture.id!==e.pointerId)return;if(!gesture.drag)cycle(gesture.start);finishGesture()});board.addEventListener('pointercancel',finishGesture);board.addEventListener('lostpointercapture',finishGesture);
document.querySelector('#undo').onclick=undo;
document.querySelector('#assist').onchange=e=>{assist=e.target.checked;update(false)};
document.querySelector('#reset').onclick=()=>{if(marks.some(Boolean)&&!confirm('要清空這座花園的所有標記嗎？'))return;marks.fill(0);history=[];won=false;started=0;elapsed=0;document.querySelector('#timer').textContent='00:00';update()};document.querySelector('#next').onclick=()=>{if(!won&&marks.some(Boolean)&&!confirm('要換一座花園嗎？目前的標記將會清空。'))return;number++;newGame()};
setInterval(()=>{if(started&&!won){elapsed=Math.floor((Date.now()-started)/1000);document.querySelector('#timer').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(elapsed%60).padStart(2,'0');save()}},1000);
try{let s=JSON.parse(localStorage.getItem('queens-garden-v2'));if(s&&s.regions?.length===64&&s.marks?.length===64&&solve(s.regions,1).length>0){({regions,solution,marks,number,elapsed}=s);assist=s.assist===true;history=Array.isArray(s.history)?s.history.filter(h=>Array.isArray(h)&&h.length===64&&h.every(v=>v===0||v===1||v===2)).slice(-200):[];started=elapsed?Date.now()-elapsed*1000:0;document.querySelector('#level').textContent='花園 '+String(number).padStart(3,'0');render()}else newGame()}catch{newGame()}
